{"Channel": {"name": "bug-georgebrown-ForecastForce", "channelID": "ch-force-42e754"}, "Message": {"User": {"userId": "eid_86044ae5", "timestamp": "2026-12-20T15:57:00", "text": "Hi team, I've found some interesting open-source bugs that are similar to the ones we're tackling in Salesforce. Let's take a look and see if we can learn anything from them! 😊", "utterranceID": "20261220-0-12a4e"}, "Reactions": []}, "ThreadReplies": [], "id": "20261220-0-12a4e"}

