{"Channel": {"name": "bug-davidgarcia-ForecastForce", "channelID": "ch-force-d1c875"}, "Message": {"User": {"userId": "eid_bd791efc", "timestamp": "2026-08-24T23:20:00", "text": "Hi team, several customers are reporting issues with ForecastForce that need our immediate attention. Let's go through them one by one. 🚀", "utterranceID": "20260824-0-19ec3"}, "Reactions": []}, "ThreadReplies": [], "id": "20260824-0-19ec3"}
