{"Channel": {"name": "bug-fionadavis-CollaborateForce", "channelID": "ch-force-8ea87e"}, "Message": {"User": {"userId": "eid_70223d0a", "timestamp": "2026-12-26T09:42:00", "text": "The issue was due to a misconfiguration in the OAuth token validation process, which was incorrectly rejecting valid tokens.", "utterranceID": "20261225-1-6a4fe"}, "Reactions": []}, "ThreadReplies": [], "id": "20261225-1-6a4fe"}
