{"Channel": {"name": "bug-fionadavis-CollaborateForce", "channelID": "ch-force-8ea87e"}, "Message": {"User": {"userId": "eid_8986ddc3", "timestamp": "2026-12-26T09:48:00", "text": "Great work, David! Thanks for resolving this so quickly. @eid_70223d0a", "utterranceID": "20261225-3-f215c"}, "Reactions": []}, "ThreadReplies": [], "id": "20261225-3-f215c"}
{"Channel": {"name": "bug-fionadavis-CollaborateForce", "channelID": "ch-force-8ea87e"}, "Message": {"User": {"userId": "eid_131494b8", "timestamp": "2026-12-26T09:49:00", "text": "Thanks, David! This should help reduce the number of support tickets we've been getting. I'll inform the support team. @eid_70223d0a", "utterranceID": "20261225-4-190ca"}, "Reactions": []}, "ThreadReplies": [], "id": "20261225-4-190ca"}
