{"Channel": {"name": "bug-emmamiller-SentimentForce", "channelID": "ch-force-664c13"}, "Message": {"User": {"userId": "eid_8658e19c", "timestamp": "2026-11-29T12:35:00", "text": "Thanks, @eid_d96fb219 and Fiona. Let me know if you notice any issues. I'll be monitoring the system as well.", "utterranceID": "20261129-8-5fb62"}, "Reactions": []}, "ThreadReplies": [], "id": "20261129-8-5fb62"}
