{"Channel": {"name": "bug-iantaylor-FeedbackForce", "channelID": "ch-force-86f5ca"}, "Message": {"User": {"userId": "eid_35e32fec", "timestamp": "2027-01-16T12:13:00", "text": "Thanks for the update, @eid_04a698e5! How did you manage to fix it?", "utterranceID": "20270116-2-9a23b"}, "Reactions": []}, "ThreadReplies": [], "id": "20270116-2-9a23b"}
